head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.MSG_NO_COMT = "위원회심사결과 내역이 없습니다. 새로 추가하시겠습니까?";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyLstBzProcsNo = "", scwin.strKeyIsurCd = "";
scwin.vScrenID = "ULDSTF05010_STK.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_getUserId = function() {
    return js_emp_no;
};
scwin.fn_ShowCalendar = function(o) {
    if ((o != undefined) && (!o.readOnly)) {
        popUpCalendar2(o);
    }
};
scwin.fn_searchCode = function() {
    var arrCid = [{
        cid: "COMITE_INVSTG_RSLT_CD",
        cnm: "cmb_ComiteInvstgRsltCd"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='COMITE_INVSTG_RSLT_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_searchReqInf = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.prelistingstk.list.cmtdelib.reqinf.condition" + "&{P}param01=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
    dts_ReqInf.DataID = encodeURI(url);
    dts_ReqInf.reset();
};
scwin.fn_search = function() {
    // 발행기관코드가 키값이다.

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRELISTING_KOSDAQ_CMTDELIB_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.prelistingstk.list.cmtdelib.condition" + "&{P}param01=" + scwin.strKeyIsurCd;
    dts_Cmt.DataID = encodeURI(url);
    dts_Cmt.reset();
};
scwin.fn_save = function(jobType) {
    if (js_dep_cd.substring(0, 2) !== '25' && // 유가 - 상장부
        js_dep_cd !== '2615') {
        //기업심사팀(2615) by nhkw
        $c.win.alert("해당 부서만 접수가 가능합니다.");
        return;
    }


    //if(jobType == "D"){}  -- 삭제일 경우, 쿼리문도 수정해줘야 함.
    //else{

    //위원회일/철회일 필수 체크
    //1줄만 있을 경우, 삭제할 수 없음
    if (med_ComiteDd.getValue() == "") {
        $c.win.alert("위원회일/철회일을 입력하여 주세요");
        med_ComiteDd.focus();
        return false;
    }
    //}

    var vScrenProcTpCd;
    if (jobType == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
        dts_ReqInf.setCellData(1, "LST_COMITE_RSLT_SAVE_EMP_NO", scwin.fn_getUserId());
        tr_Save.Action = "/Prelisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveCmtdelRslt";
        tr_Save.KeyName = "toinb_dataid4";
        tr_Save.KeyValue = "JSP(I:pInpReqInf=dts_ReqInf,I:pInpCmt=dts_Cmt)";
        tr_Save.Post();
    } else {
        $c.win.alert(scwin.MGS_NO_UPDT);
    }
};
scwin.fn_addNewCmt = function() {
    dts_Cmt.insertRow();
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO", scwin.strKeyLstBzProcsNo);
    scwin.fn_searchReqInf();
    scwin.fn_setKeyCtrOnAdd(); // 추가상태에서는  key컬럼수정가능

};
scwin.fn_DeleteRow = function() {
    $c.cp.removeRow(dts_Cmt, dts_Cmt.getRowPosition());
    scwin.fn_save("D");
};
scwin.fn_setKeyCtrOnAdd = function() {
    $c.lc.fn_setCtrWritable([med_ComiteDd]);
};
scwin.fn_setKeyCtrOnUpd = function() {
    $c.lc.fn_setCtrReadOnly([med_ComiteDd]);
};
scwin.dts_Cmt_OnLoadCompleted = function(rowcount) {
    if (dts_Cmt.getTotalRow() > 0) {
        scwin.fn_setKeyCtrOnUpd(); // 조회직후에는 수정상태
        scwin.fn_searchReqInf();
    }
};
scwin.dts_Cmt_OnRowPosChanged = function(row) {
    if (dts_Cmt.getTotalRow() > 0) {
        if (dts_Cmt.getCellData(row, "BZ_PROCS_NO") != "") {
            scwin.fn_searchReqInf();
        }

    }
};
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {

};
scwin.tr_Save_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.tr_Save_OnSuccess = function() {
    $c.win.alert(scwin.MSG_TR_DOME);
    scwin.fn_search();

    //상장위원회일, 심사구분 reLoad
    var parentWin = $c.frame.path("../");
    parentWin.fn_read_sync();
};
scwin.img_SetComiteDd_onclick = function() {
    scwin.fn_ShowCalendar(med_ComiteDd);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var arr = new Array();
    $c.elw.fn_searchCode();
    scwin.fn_GetPar = $c.frame.path("../").scwin.fn_GetPar;
    scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arr);
    }
    txb_IsurCd.setValue((arr.length >= 1 ? arr[0] : ""));
    scwin.strKeyIsurCd = (arr.length >= 1 ? arr[0] : "");
    scwin.strKeyLstBzProcsNo = (arr.length >= 2 ? arr[1] : "");
    txb_CoNm.setValue((arr.length >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

    if (arr.length > 2) {
        scwin.fn_search();
    }
};
